// Biome Triad's flora in Aetherion's realms.
//
// Each realm grows the species of the Biome Triad world it corresponds to (oaks and beeches in the forest, bald
// cypress in the marsh, spruce on the ice, acacia and baobab on the plateau). Species are generated by the code
// lifted verbatim from Biome Triad (biome-flora.generated.js). Trees near the player are full meshes; farther
// tiles draw one crossed card per tree from a picture of that species baked once on this device.
import * as THREE from 'three';
import { SPECIES_DEF, genTree, setCardDensity, tex } from './biome-flora.generated.js';

// Realm biome -> [species, share, height in metres a typical specimen stands in play].
// Biome Triad's trees are life-size (a 39 m beech); these heights keep the third-person camera under the crowns.
export const REALM_SPECIES = Object.freeze({
  forest: [['forestOak', 4, 17], ['forestBeech', 3, 19], ['forestElder', 2, 21], ['shrub', 2, 5]],
  meadow: [['vilOak', 4, 14], ['vilApple', 3, 6.5], ['vilPoplar', 2, 18], ['vilWillow', 2, 10]],
  marsh: [['marshCypress', 4, 17], ['marshWillow', 3, 10.5], ['marshAlder', 3, 8.5]],
  glacial: [['taigaSpruce', 4, 15], ['taigaSpruceTall', 2, 19], ['taigaKrumm', 3, 5.5], ['taigaBirch', 2, 12]],
  alpine: [['alpineFir', 4, 18], ['alpineLarch', 3, 17], ['alpinePine', 2, 12], ['alpineDwarf', 3, 4]],
  highland: [['alpinePine', 4, 12], ['taigaBirch', 3, 12], ['alpineDwarf', 3, 4]],
  coast: [['coconut', 4, 12], ['island', 3, 11], ['datePalm', 2, 11]],
  cliffs: [['vilOak', 3, 14], ['forestBeech', 2, 18], ['vilPoplar', 2, 17], ['shrub', 2, 5]],
  canyon: [['canyonCotton', 3, 13], ['canyonJuniper', 4, 5.5], ['canyonPinyon', 3, 7.5]],
  badlands: [['savAcacia', 3, 9], ['savBush', 4, 3.4], ['canyonJuniper', 3, 5]],
  plateau: [['savAcacia', 4, 10], ['savBaobab', 2, 14], ['savFever', 2, 13], ['savBush', 3, 3.4]],
  volcanic: [['canyonJuniper', 3, 5], ['savBush', 3, 3], ['canyonPinyon', 2, 7]],
  crimson: [['blossom', 5, 10], ['cypress', 3, 15], ['shrub', 2, 4.5]],
  terraces: [['blossom', 3, 10], ['vilApple', 3, 6.5], ['cypress', 3, 15]],
  industrial: [['vilPoplar', 3, 17], ['shrub', 3, 4.5]],
});
// Leaf tint per realm, multiplied over the species' own colours (white leaves the species as authored).
const REALM_TINT = { crimson: 0xd98a86, volcanic: 0xa79a84, glacial: 0xdfe8ee, badlands: 0xc9bf9a, industrial: 0xb9bdb0 };

export function createRealmFlora(ctx, wind) {
  const quality = ctx.quality?.name ?? 'high';
  const low = quality === 'low', medium = quality === 'medium';
  const cache = new Map(), white = new THREE.Color(1, 1, 1);
  const cardGeometry = crossedCards();

  function sway(material, amount) {
    material.onBeforeCompile = (shader) => {
      shader.uniforms.windTime = wind.time;
      shader.vertexShader = shader.vertexShader.replace('#include <common>', '#include <common>\nuniform float windTime;')
        .replace('#include <begin_vertex>', `#include <begin_vertex>
        #ifdef USE_INSTANCING
        float swayPhase = windTime * 1.1 + instanceMatrix[3].x * .17 + instanceMatrix[3].z * .21;
        transformed.x += sin(swayPhase) * ${amount.toFixed(4)} * max(position.y, 0.);
        transformed.z += cos(swayPhase * .83) * ${(amount * .6).toFixed(4)} * max(position.y, 0.);
        #endif`);
    };
    return material;
  }

  /** Generate a species once: full meshes, materials and the baked far card. */
  function species(key) {
    if (cache.has(key)) return cache.get(key);
    const def = SPECIES_DEF[key];
    if (!def) { cache.set(key, null); return null; }
    let built = null;
    try {
      setCardDensity(low ? .3 : medium ? .45 : .6);
      const tree = def.build ? def.build() : genTree(def.tree, def.seed);
      // Leaf atlases and bark are painted on a canvas; without one (tests, a server) trees keep their shape and trunks.
      const canPaint = typeof document !== 'undefined';
      const leafMap = canPaint ? def.leaves() : null, woodMap = canPaint ? (def.barkMap ? def.barkMap() : tex.bark) : null;
      const leafMaterial = sway(new THREE.MeshStandardMaterial({ name: `flora-leaf-${key}`, map: leafMap, alphaTest: .5, side: THREE.DoubleSide, vertexColors: true, roughness: def.roughness ?? .62, metalness: 0 }), .012);
      const woodMaterial = sway(new THREE.MeshStandardMaterial({ name: `flora-wood-${key}`, map: woodMap, color: def.bark, vertexColors: true, roughness: .92, metalness: 0 }), .012);
      built = { key, wood: tree.wood, leaf: tree.leaf, leafMaterial, woodMaterial, height: tree.H, spread: tree.S, trunk: def.tree?.r ?? .3 };
      built.card = canPaint && ctx.renderer ? bake(built) : { target: null, material: new THREE.MeshStandardMaterial({ name: `flora-card-${key}`, color: 0x4c6240, side: THREE.DoubleSide, roughness: 1 }) };
    } catch (error) { console.warn('[flora] Species unavailable', key, error); built = null; }
    cache.set(key, built);
    return built;
  }

  /** Photograph a species from the side into a small texture; far tiles draw that on two crossed cards. */
  function bake(sp) {
    const renderer = ctx.renderer, size = low ? 128 : 256;
    const target = new THREE.WebGLRenderTarget(size, size, { depthBuffer: true });
    target.texture.colorSpace = THREE.SRGBColorSpace; target.texture.generateMipmaps = true; target.texture.minFilter = THREE.LinearMipmapLinearFilter;
    const stage = new THREE.Scene();
    stage.add(new THREE.HemisphereLight(0xdfeaff, 0x57503f, 2.2));
    const key = new THREE.DirectionalLight(0xfff2d8, 2.4); key.position.set(-.5, 1, .8); stage.add(key);
    const wood = new THREE.Mesh(sp.wood, new THREE.MeshStandardMaterial({ map: sp.woodMaterial.map, color: sp.woodMaterial.color, vertexColors: true, roughness: .92 }));
    const leaf = new THREE.Mesh(sp.leaf, new THREE.MeshStandardMaterial({ map: sp.leafMaterial.map, alphaTest: .5, side: THREE.DoubleSide, vertexColors: true, roughness: .7 }));
    stage.add(wood, leaf);
    const half = sp.spread / 2, camera = new THREE.OrthographicCamera(-half, half, sp.height, 0, .1, sp.spread * 4);
    camera.position.set(0, 0, sp.spread * 2); camera.lookAt(0, 0, 0);
    const previous = { target: renderer.getRenderTarget(), alpha: renderer.getClearAlpha(), colour: renderer.getClearColor(new THREE.Color()), tone: renderer.toneMapping, auto: renderer.autoClear };
    renderer.setRenderTarget(target); renderer.setClearColor(0x000000, 0); renderer.toneMapping = THREE.NoToneMapping; renderer.autoClear = true;
    renderer.clear(); renderer.render(stage, camera);
    renderer.setRenderTarget(previous.target); renderer.setClearColor(previous.colour, previous.alpha); renderer.toneMapping = previous.tone; renderer.autoClear = previous.auto;
    wood.material.dispose(); leaf.material.dispose();
    const material = new THREE.MeshStandardMaterial({ name: `flora-card-${sp.key}`, map: target.texture, alphaTest: .42, side: THREE.DoubleSide, roughness: 1, metalness: 0 });
    return { target, material };
  }

  const dummy = new THREE.Object3D(), tint = new THREE.Color();
  function instances(geometry, material, list, scaleOf, shadow) {
    const mesh = new THREE.InstancedMesh(geometry, material, list.length);
    for (let i = 0; i < list.length; i++) {
      const item = list[i], [sx, sy, sz] = scaleOf(item);
      dummy.position.set(item.x, item.y, item.z); dummy.rotation.set(0, item.turn, 0); dummy.scale.set(sx, sy, sz); dummy.updateMatrix();
      mesh.setMatrixAt(i, dummy.matrix); mesh.setColorAt(i, item.colour);
    }
    mesh.castShadow = shadow; mesh.receiveShadow = shadow; mesh.computeBoundingSphere();
    return mesh;
  }

  return {
    /** Choose a species for a realm from a 0..1 roll. Returns { key, height } or null when the realm grows nothing. */
    choose(biome, roll) {
      const list = REALM_SPECIES[biome]; if (!list) return null;
      let total = 0; for (const entry of list) total += entry[1];
      let at = roll * total;
      for (const entry of list) { at -= entry[1]; if (at <= 0) return { key: entry[0], height: entry[2] }; }
      return { key: list[0][0], height: list[0][2] };
    },
    tint(biome, shade) { return tint.set(REALM_TINT[biome] ?? 0xffffff).multiplyScalar(shade).clone(); },
    /**
     * Build one tile's trees. `plants` is a list of { key, x, y, z, height, turn, colour } where height is how tall
     * that specimen stands in metres. Returns { near, far, trunks } with trunks as [x, z, radius].
     */
    tile(plants) {
      const near = new THREE.Group(), far = new THREE.Group(), trunks = [];
      near.name = 'Flora (full)'; far.name = 'Flora (cards)';
      const bySpecies = new Map();
      for (const plant of plants) { if (!bySpecies.has(plant.key)) bySpecies.set(plant.key, []); bySpecies.get(plant.key).push(plant); }
      for (const [key, list] of bySpecies) {
        const sp = species(key); if (!sp) continue;
        for (const plant of list) {
          plant.colour ??= white; plant.scale = plant.height / sp.height;
          // Bushes and dwarf trees are walked through; anything with a real trunk is solid.
          const radius = sp.trunk * plant.scale * .9;
          if (radius >= .14) trunks.push([plant.x, plant.z, Math.max(.26, radius)]);
        }
        const uniform = (plant) => [plant.scale, plant.scale, plant.scale];
        near.add(instances(sp.wood, sp.woodMaterial, list, uniform, !low), instances(sp.leaf, sp.leafMaterial, list, uniform, !low));
        far.add(instances(cardGeometry, sp.card.material, list, (plant) => [sp.spread * plant.scale, sp.height * plant.scale, sp.spread * plant.scale], false));
      }
      return { near, far, trunks };
    },
    stats: () => ({ species: [...cache.entries()].filter(([, value]) => value).map(([key]) => key) }),
    dispose() {
      for (const sp of cache.values()) { if (!sp) continue; sp.wood.dispose(); sp.leaf.dispose(); sp.leafMaterial.dispose(); sp.woodMaterial.dispose(); sp.card.material.dispose(); sp.card.target?.dispose(); }
      cache.clear(); cardGeometry.dispose();
    },
  };
}

/** Two unit cards crossed at right angles, standing on the origin: 1 wide, 1 tall. */
function crossedCards() {
  const positions = [], uvs = [], normals = [], index = [];
  for (const [dx, dz] of [[1, 0], [0, 1]]) {
    const base = positions.length / 3;
    positions.push(-.5 * dx, 0, -.5 * dz, .5 * dx, 0, .5 * dz, .5 * dx, 1, .5 * dz, -.5 * dx, 1, -.5 * dz);
    uvs.push(0, 0, 1, 0, 1, 1, 0, 1);
    // Upward normals light a card like the canopy it stands for instead of a wall.
    for (let i = 0; i < 4; i++) normals.push(0, 1, 0);
    index.push(base, base + 1, base + 2, base, base + 2, base + 3);
  }
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geometry.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
  geometry.setAttribute('normal', new THREE.Float32BufferAttribute(normals, 3));
  geometry.setIndex(index);
  return geometry;
}
